/// A member appearing inside an interface body: a regular method, a property
/// shorthand (`Name: Type;`), or an event shorthand (`event Name: Handler;`).
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

/// Represents a property shorthand declaration inside an interface body.
///
/// Parsed from the syntax `[#[get] | #[set]] Name: Type;`.  Without any attribute,
/// both a getter and a setter are generated; with `#[get]`, only a getter; with
/// `#[set]`, only a setter.
#[derive(Debug)]
pub struct Property {
    pub attrs: Vec<syn::Attribute>,
    pub name: syn::Ident,
    pub ty: syn::Type,
}

