    /// Encodes a property shorthand as `get_Name` and/or `put_Name` methods with the
    /// `SpecialName` flag.  Without any attribute both accessors are emitted; `#[get]`
    /// emits only the getter and `#[set]` only the setter.
    fn encode_interface_property(
        &mut self,
        property: &Property,
        winrt: bool,
        base_flags: metadata::MethodAttributes,
        collect_guid: bool,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
    ) -> Result<(), Error> {
        let mut has_get = false;
        let mut has_set = false;

        for attr in &property.attrs {
            if attr.path().is_ident("get") {
                has_get = true;
            } else if attr.path().is_ident("set") {
                has_set = true;
            } else {
                return self.err(
                    attr,
                    "only `#[get]` and `#[set]` attributes are supported on properties",
                );
            }
        }

        if has_get && has_set {
            return self.err(
                &property.name,
                "property cannot have both `#[get]` and `#[set]` attributes",
            );
        }

        // No attribute means a read-write property: emit both accessors.
        let emit_get = has_get || !has_set;
        let emit_set = has_set || !has_get;

        let ty = self.encode_type(&property.ty)?;
        if winrt {
            self.validate_type_is_winrt(&property.ty, &ty)?;
        }

        let name = property.name.to_string();

        if emit_get {
            self.encode_special_method(
                &format!("get_{name}"),
                &[],
                ty.clone(),
                base_flags,
                collect_guid,
                method_signatures,
            )?;
        }

        if emit_set {
            self.encode_special_method(
                &format!("put_{name}"),
                &[("value", &ty)],
                metadata::Type::Void,
                base_flags,
                collect_guid,
                method_signatures,
            )?;
        }

        Ok(())
    }

