        winrt: bool,
        base_flags: metadata::MethodAttributes,
        collect_guid: bool,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
    ) -> Result<(), Error> {
        let handler = self.encode_type(&event.handler_ty)?;
        if winrt {
            self.validate_type_is_winrt(&event.handler_ty, &handler)?;
        }

        let token = metadata::Type::value_named("Windows.Foundation", "EventRegistrationToken");
        let name = event.name.to_string();

        self.encode_special_method(
