        let name = name.ident.to_string();
        let ty = self.encode_type(&param.ty)?;
        let attributes = self.parse_param_attributes(&param.attrs, &ty)?;

        Ok(Param {
            name,
            ty,
            attributes,
            attrs: param.attrs.clone(),
        })
    }

