/// property shorthand (`Name: Type;`), `SpecialName` add/remove pairs to event
/// shorthand (`event Name: Handler;`, WinRT only), and falling back to the regular
/// method representation for anything else.
fn write_members(
    namespace: &str,
    item: &metadata::reader::TypeDef,
    generics: &[metadata::Type],
) -> Result<Vec<TokenStream>, Error> {
    let methods: Vec<metadata::reader::MethodDef> = item.methods().collect();
    let mut consumed = vec![false; methods.len()];
    let winrt = item
        .flags()
        .contains(metadata::TypeAttributes::WindowsRuntime);

    let mut output = Vec::new();

    for i in 0..methods.len() {
        if consumed[i] {
            continue;
        }

        let method = &methods[i];
        let is_special = method
            .flags()
            .contains(metadata::MethodAttributes::SpecialName);

        if is_special {
            let name = method.name();

            // Property getter: `get_Name` → optionally paired with `put_Name`.
            if let Some(prop) = name.strip_prefix("get_") {
                consumed[i] = true;
                let signature = method.signature(generics);
                let ty = write_type(namespace, &signature.return_type);
                let prop_ident = write_ident(prop);

                let setter = find_unconsumed(&methods, &consumed, i, &format!("put_{prop}"));
                if let Some(j) = setter {
                    consumed[j] = true;
                    output.push(quote! { #prop_ident: #ty; });
                } else {
                    output.push(quote! { #[get] #prop_ident: #ty; });
                }
                continue;
            }

            // Property setter with no matching getter: `put_Name` → `#[set]`.
            if let Some(prop) = name.strip_prefix("put_") {
                consumed[i] = true;
                let signature = method.signature(generics);
                let prop_ident = write_ident(prop);
                let value_ty = signature
                    .types
                    .first()
                    .map(|ty| write_type(namespace, ty))
                    .unwrap_or_else(|| quote! { void });
                output.push(quote! { #[set] #prop_ident: #value_ty; });
                continue;
            }

            // Event: `add_Name` paired with `remove_Name` (WinRT interfaces only).
            if winrt {
                if let Some(event) = name.strip_prefix("add_") {
                    if let Some(j) =
                        find_unconsumed(&methods, &consumed, i, &format!("remove_{event}"))
                    {
                        consumed[i] = true;
                        consumed[j] = true;
                        let signature = method.signature(generics);
                        let event_ident = write_ident(event);
                        let handler_ty = signature
                            .types
                            .first()
                            .map(|ty| write_type(namespace, ty))
                            .unwrap_or_else(|| quote! { void });
                        output.push(quote! { event #event_ident: #handler_ty; });
                        continue;
                    }
                }
            }
        }

        consumed[i] = true;
        output.push(write_method(namespace, method, generics)?);
    }

    Ok(output)
}

/// Finds the index of an unconsumed method named `name`, searching forward from `from`
/// and wrapping around.  Used to locate the paired `put_`/`remove_` accessor for a
/// `get_`/`add_` method.
fn find_unconsumed(
    methods: &[metadata::reader::MethodDef],
    consumed: &[bool],
    from: usize,
    name: &str,
) -> Option<usize> {
    let len = methods.len();
    for offset in 0..len {
        let idx = (from + offset) % len;
        if !consumed[idx] && methods[idx].name() == name {
            return Some(idx);
        }
    }
    None
}

